import { primaryFailures } from '../../packages/cli/src/catalog/runtime.mjs'

/** Exact source of Start's public defaults, derived from the CLI catalog. */
export const failureDefaultsSource = () =>
  '// Generated by scripts/quality/failure-defaults.mjs\n' +
  'export const failureDefaults = {\n' +
  Object.entries(primaryFailures)
    .map(
      ([code, { status, message }]) => `  ${code}: { status: ${status}, message: '${message}' },\n`,
    )
    .join('') +
  '} as const\n'
